import data from '../data/dora-4.0.json' with { type: 'json' };
import type { Column, Taxonomy, Template } from './types.ts';

/**
 * The EBA DORA taxonomy 4.0 (reporting framework 4.0, errata 5), with the
 * ITS column descriptions and the EBA validation rules, as generated by
 * `scripts/generate-taxonomy.ts` from the official files.
 */
export const DORA_4_0: Taxonomy = data as unknown as Taxonomy;

const byCode = new Map<string, Template>(DORA_4_0.templates.map((t) => [t.code, t]));

/** Returns the template with this code (e.g. `B_02.02`), or undefined. */
export function findTemplate(code: string, taxonomy: Taxonomy = DORA_4_0): Template | undefined {
  return taxonomy === DORA_4_0 ? byCode.get(code) : taxonomy.templates.find((t) => t.code === code);
}

/** Returns the column of a template, or undefined. */
export function findColumn(template: Template, code: string): Column | undefined {
  return template.columns.find((c) => c.code === code);
}

/** Members of a column's closed list, or an empty list. */
export function allowedValues(column: Column, taxonomy: Taxonomy = DORA_4_0): readonly string[] {
  return column.enumeration === null ? [] : (taxonomy.enumerations[column.enumeration] ?? []);
}

/** The English label of a closed-list member, e.g. `eba_GA:LU` → `Luxembourg`. */
export function memberLabel(qname: string, taxonomy: Taxonomy = DORA_4_0): string | undefined {
  return taxonomy.labels[qname];
}
